import "server-only";

import { del, head } from "@vercel/blob";

/** Public URL for a stored file. `key` is the blob pathname (`${userId}/...`). */
export async function getFileUrl(key: string): Promise<string> {
  const blob = await head(key);
  return blob.url;
}

export async function deleteFile(key: string): Promise<void> {
  await del(key);
}

import { upload } from "@vercel/blob/client";

import type { StoredFile } from "./types";

/**
 * Direct-from-client upload (no file bytes pass through our functions).
 * `GET /api/upload` returns the caller's key prefix (`${userId}/`); the same
 * route then enforces that prefix when issuing the upload token.
 */
export async function uploadFile(
  file: File,
  opts?: { folder?: string },
): Promise<StoredFile> {
  const res = await fetch("/api/upload");
  if (!res.ok) throw new Error("Not authorized to upload");
  const { prefix } = (await res.json()) as { prefix: string };

  const folder = opts?.folder?.replace(/^\/+|\/+$/g, "");
  const name = file.name.replace(/[^\w.-]+/g, "_");
  const pathname = `${prefix}${folder ? `${folder}/` : ""}${name}`;

  const blob = await upload(pathname, file, {
    access: "public",
    handleUploadUrl: "/api/upload",
  });
  return { key: blob.pathname, url: blob.url };
}

import { auth } from "@clerk/nextjs/server";
import { handleUpload, type HandleUploadBody } from "@vercel/blob/client";
import { NextResponse } from "next/server";

const ALLOWED_CONTENT_TYPES = [
  "image/jpeg",
  "image/png",
  "image/webp",
  "image/gif",
  "application/pdf",
];
const MAX_SIZE = 10 * 1024 * 1024; // 10 MB

/** Returns the caller's key prefix; the client builds its pathname from it. */
export async function GET(): Promise<NextResponse> {
  const { userId } = await auth();
  if (!userId) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
  return NextResponse.json({ prefix: `${userId}/` });
}

export async function POST(request: Request): Promise<NextResponse> {
  const { userId } = await auth();
  if (!userId) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const body = (await request.json()) as HandleUploadBody;

  try {
    const json = await handleUpload({
      body,
      request,
      onBeforeGenerateToken: async (pathname) => {
        // Keys must live under the caller's own `${userId}/` prefix.
        if (!pathname.startsWith(`${userId}/`) || pathname.includes("..")) {
          throw new Error("Invalid upload path");
        }
        return {
          allowedContentTypes: ALLOWED_CONTENT_TYPES,
          maximumSizeInBytes: MAX_SIZE,
          addRandomSuffix: true,
          tokenPayload: JSON.stringify({ userId }),
        };
      },
    });
    return NextResponse.json(json);
  } catch (error) {
    return NextResponse.json(
      { error: (error as Error).message },
      { status: 400 },
    );
  }
}
